local killauraTelemetry = {
	Enabled = false,
	SwingCount = 0,
	ConfirmedCount = 0,
	ExpiredCount = 0,
	DroppedCount = 0,
	SwingGapCount = 0,
	HitGapCount = 0,
	ConfirmationCount = 0,
	AverageSwingGap = 0,
	AverageHitGap = 0,
	AverageConfirmationDelay = 0,
