			holder.Name = 'Holder'
			holder.Position = UDim2.fromOffset(10, 37)
			holder.Size = UDim2.new(1, -20, 0, 2)
			holder.Parent = colorslidercustom
			local uigradient = Instance.new('UIGradient')
