function whitelist:get(plr)
	local entry = self.data.WhitelistedUsers[tostring(plr.UserId)]
	if entry then
		local level = entry.level or 1
		return level, entry.attackable or whitelist.localprio >= level, entry.tags
	end
	return 0, true
end
