run(function()
	local NameTags
	local Targets
	local Color
	local Background
	local DisplayName
	local Health
	local Distance
	local DrawingToggle
	local Scale
	local FontOption
	local Teammates
	local DistanceCheck
	local DistanceLimit
	local Strings, Sizes, Reference = {}, {}, {}
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui
	local methodused
	
	local Added = {
		Normal = function(ent)
			if not Targets.Players.Enabled and ent.Player then return end
			if not Targets.NPCs.Enabled and ent.NPC then return end
			if Teammates.Enabled and (not ent.Targetable) and (not ent.Friend) then return end
			if vape.ThreadFix then
				setthreadidentity(8)
			end
	
			Strings[ent] = ent.Player and whitelist:tag(ent.Player, true, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name
	
			if Health.Enabled then
				local healthColor = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
				Strings[ent] = Strings[ent]..' <font color="rgb('..tostring(math.floor(healthColor.R * 255))..','..tostring(math.floor(healthColor.G * 255))..','..tostring(math.floor(healthColor.B * 255))..')">'..math.round(ent.Health)..'</font>'
			end
	
			if Distance.Enabled then
				Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '..Strings[ent]
			end
	
			local nametag = Instance.new('TextLabel')
			nametag.TextSize = 14 * Scale.Value
			nametag.FontFace = FontOption.Value
			local size = getfontsize(removeTags(Strings[ent]), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
			nametag.Name = ent.Player and ent.Player.Name or ent.Character.Name
			nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
			nametag.AnchorPoint = Vector2.new(0.5, 1)
			nametag.BackgroundColor3 = Color3.new()
			nametag.BackgroundTransparency = Background.Value
			nametag.BorderSizePixel = 0
			nametag.Visible = false
			nametag.Text = Strings[ent]
			nametag.TextColor3 = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
			nametag.RichText = true
			nametag.Parent = Folder
			Reference[ent] = nametag
		end,
		Drawing = function(ent)
			if not Targets.Players.Enabled and ent.Player then return end
			if not Targets.NPCs.Enabled and ent.NPC then return end
			if Teammates.Enabled and (not ent.Targetable) and (not ent.Friend) then return end
	
			local nametag = {}
			nametag.BG = Drawing.new('Square')
			nametag.BG.Filled = true
			nametag.BG.Transparency = 1 - Background.Value
			nametag.BG.Color = Color3.new()
			nametag.BG.ZIndex = 1
			nametag.Text = Drawing.new('Text')
			nametag.Text.Size = 15 * Scale.Value
			nametag.Text.Font = 0
			nametag.Text.ZIndex = 2
			Strings[ent] = ent.Player and whitelist:tag(ent.Player, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name
	
			if Health.Enabled then
				Strings[ent] = Strings[ent]..' '..math.round(ent.Health)
			end
	
			if Distance.Enabled then
				Strings[ent] = '[%s] '..Strings[ent]
			end
	
			nametag.Text.Text = Strings[ent]
			nametag.Text.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
			nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
			Reference[ent] = nametag
		end
	}
	
	local Removed = {
		Normal = function(ent)
			local v = Reference[ent]
			if v then
				if vape.ThreadFix then
					setthreadidentity(8)
				end
				Reference[ent] = nil
				Strings[ent] = nil
				Sizes[ent] = nil
				v:Destroy()
			end
		end,
		Drawing = function(ent)
			local v = Reference[ent]
			if v then
				if vape.ThreadFix then
					setthreadidentity(8)
				end
				Reference[ent] = nil
				Strings[ent] = nil
				Sizes[ent] = nil
				for _, obj in v do
					pcall(function()
						obj.Visible = false
						obj:Remove()
					end)
				end
			end
		end
	}
	
	local Updated = {
		Normal = function(ent)
			local nametag = Reference[ent]
			if nametag then
				if vape.ThreadFix then
					setthreadidentity(8)
				end
				Sizes[ent] = nil
				Strings[ent] = ent.Player and whitelist:tag(ent.Player, true, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name
	
				if Health.Enabled then
					local color = Color3.fromHSV(math.clamp(ent.Health / ent.MaxHealth, 0, 1) / 2.5, 0.89, 0.75)
					Strings[ent] = Strings[ent]..' <font color="rgb('..tostring(math.floor(color.R * 255))..','..tostring(math.floor(color.G * 255))..','..tostring(math.floor(color.B * 255))..')">'..math.round(ent.Health)..'</font>'
				end
	
				if Distance.Enabled then
					Strings[ent] = '<font color="rgb(85, 255, 85)">[</font><font color="rgb(255, 255, 255)">%s</font><font color="rgb(85, 255, 85)">]</font> '..Strings[ent]
				end
	
				local size = getfontsize(removeTags(Strings[ent]), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
				nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
				nametag.Text = Strings[ent]
			end
		end,
		Drawing = function(ent)
			local nametag = Reference[ent]
			if nametag then
				if vape.ThreadFix then
					setthreadidentity(8)
				end
				Sizes[ent] = nil
				Strings[ent] = ent.Player and whitelist:tag(ent.Player, true)..(DisplayName.Enabled and ent.Player.DisplayName or ent.Player.Name) or ent.Character.Name
	
				if Health.Enabled then
					Strings[ent] = Strings[ent]..' '..math.round(ent.Health)
				end
	
				if Distance.Enabled then
					Strings[ent] = '[%s] '..Strings[ent]
					nametag.Text.Text = entitylib.isAlive and string.format(Strings[ent], math.floor((entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude)) or Strings[ent]
				else
					nametag.Text.Text = Strings[ent]
				end
	
				nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
				nametag.Text.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
			end
		end
	}
	
	local ColorFunc = {
		Normal = function(hue, sat, val)
			local color = Color3.fromHSV(hue, sat, val)
			for i, v in Reference do
				v.TextColor3 = entitylib.getEntityColor(i) or color
			end
		end,
		Drawing = function(hue, sat, val)
			local color = Color3.fromHSV(hue, sat, val)
			for i, v in Reference do
				v.Text.Color = entitylib.getEntityColor(i) or color
			end
		end
	}
	
	local Loop = {
		Normal = function()
			for ent, nametag in Reference do
				if DistanceCheck.Enabled then
					local distance = entitylib.isAlive and (entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude or math.huge
					if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
						nametag.Visible = false
						continue
					end
				end
	
				local headPos, headVis = gameCamera:WorldToViewportPoint(ent.RootPart.Position + Vector3.new(0, ent.HipHeight + 1, 0))
				nametag.Visible = headVis
				if not headVis then
					continue
				end
	
				if Distance.Enabled then
					local mag = entitylib.isAlive and math.floor((entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude) or 0
					if Sizes[ent] ~= mag then
						nametag.Text = string.format(Strings[ent], mag)
						local size = getfontsize(removeTags(nametag.Text), nametag.TextSize, nametag.FontFace, Vector2.new(100000, 100000))
						nametag.Size = UDim2.fromOffset(size.X + 8, size.Y + 7)
						Sizes[ent] = mag
					end
				end
				nametag.Position = UDim2.fromOffset(headPos.X, headPos.Y)
			end
		end,
		Drawing = function()
			for ent, nametag in Reference do
				if DistanceCheck.Enabled then
					local distance = entitylib.isAlive and (entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude or math.huge
					if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
						nametag.Text.Visible = false
						nametag.BG.Visible = false
						continue
					end
				end
	
				local headPos, headVis = gameCamera:WorldToViewportPoint(ent.RootPart.Position + Vector3.new(0, ent.HipHeight + 1, 0))
				nametag.Text.Visible = headVis
				nametag.BG.Visible = headVis
				if not headVis then
					continue
				end
	
				if Distance.Enabled then
					local mag = entitylib.isAlive and math.floor((entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude) or 0
					if Sizes[ent] ~= mag then
						nametag.Text.Text = string.format(Strings[ent], mag)
						nametag.BG.Size = Vector2.new(nametag.Text.TextBounds.X + 8, nametag.Text.TextBounds.Y + 7)
						Sizes[ent] = mag
					end
				end
				nametag.BG.Position = Vector2.new(headPos.X - (nametag.BG.Size.X / 2), headPos.Y - nametag.BG.Size.Y)
				nametag.Text.Position = nametag.BG.Position + Vector2.new(4, 3)
			end
		end
	}
	
	NameTags = vape.Categories.Render:CreateModule({
		Name = 'NameTags',
		Function = function(callback)
			if callback then
				methodused = DrawingToggle.Enabled and 'Drawing' or 'Normal'
				if Removed[methodused] then
					NameTags:Clean(entitylib.Events.EntityRemoved:Connect(Removed[methodused]))
				end
				if Added[methodused] then
					for _, v in entitylib.List do
						if Reference[v] then
							Removed[methodused](v)
						end
						Added[methodused](v)
					end
					NameTags:Clean(entitylib.Events.EntityAdded:Connect(function(ent)
						if Reference[ent] then
							Removed[methodused](ent)
						end
						Added[methodused](ent)
					end))
				end
				if Updated[methodused] then
					NameTags:Clean(entitylib.Events.EntityUpdated:Connect(Updated[methodused]))
					for _, v in entitylib.List do
						Updated[methodused](v)
					end
				end
				if ColorFunc[methodused] then
					NameTags:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function()
						ColorFunc[methodused](Color.Hue, Color.Sat, Color.Value)
					end))
				end
				if Loop[methodused] then
					NameTags:Clean(runService.RenderStepped:Connect(Loop[methodused]))
				end
			else
				if Removed[methodused] then
					for i in Reference do
						Removed[methodused](i)
					end
				end
			end
		end,
		Tooltip = 'Renders nametags on entities through walls.'
	})
	Targets = NameTags:CreateTargets({
		Players = true,
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	FontOption = NameTags:CreateFont({
		Name = 'Font',
		Blacklist = 'Arial',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Color = NameTags:CreateColorSlider({
		Name = 'Player Color',
		Function = function(hue, sat, val)
			if NameTags.Enabled and ColorFunc[methodused] then
				ColorFunc[methodused](hue, sat, val)
			end
		end
	})
	Scale = NameTags:CreateSlider({
		Name = 'Scale',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = 1,
		Min = 0.1,
		Max = 1.5,
		Decimal = 10
	})
	Background = NameTags:CreateSlider({
		Name = 'Transparency',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = 0.5,
		Min = 0,
		Max = 1,
		Decimal = 10
	})
	Health = NameTags:CreateToggle({
		Name = 'Health',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	Distance = NameTags:CreateToggle({
		Name = 'Distance',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	DisplayName = NameTags:CreateToggle({
		Name = 'Use Displayname',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = true
	})
	Teammates = NameTags:CreateToggle({
		Name = 'Priority Only',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end,
		Default = true,
		Tooltip = 'Hides teammates & non targetable entities'
	})
	DrawingToggle = NameTags:CreateToggle({
		Name = 'Drawing',
		Function = function()
			if NameTags.Enabled then
				NameTags:Toggle()
				NameTags:Toggle()
			end
		end
	})
	DistanceCheck = NameTags:CreateToggle({
		Name = 'Distance Check',
		Function = function(callback)
			DistanceLimit.Object.Visible = callback
		end
	})
	DistanceLimit = NameTags:CreateTwoSlider({
		Name = 'Player Distance',
		Min = 0,
		Max = 256,
		DefaultMin = 0,
		DefaultMax = 64,
		Darker = true,
		Visible = false
	})
end)
	
run(function()
	local PlayerModel
	local Scale
	local Local
	local Mesh
	local Texture
	local Rots = {}
	local models = {}
	local modelGeneration = 0
	
	local function addMesh(ent, generation)
		if generation and generation ~= modelGeneration then return end
		if not (PlayerModel and PlayerModel.Enabled) then return end
		if vape.ThreadFix then 
			setthreadidentity(8)
		end
		local root = ent.RootPart
		if not (root and root.Parent) then return end
		local previous = models[root]
		if previous then
			pcall(function() previous:Destroy() end)
			models[root] = nil
		end
		local part = Instance.new('Part')
		part.Size = Vector3.new(3, 3, 3)
		part.CFrame = root.CFrame * CFrame.Angles(math.rad(Rots[1].Value), math.rad(Rots[2].Value), math.rad(Rots[3].Value))
		part.CanCollide = false
		part.CanQuery = false
		part.Massless = true
		part.Parent = workspace
		local meshd = Instance.new('SpecialMesh')
		meshd.MeshId = Mesh.Value
		meshd.TextureId = Texture.Value
		meshd.Scale = Vector3.one * Scale.Value
		meshd.Parent = part
		local weld = Instance.new('WeldConstraint')
		weld.Part0 = part
		weld.Part1 = root
		weld.Parent = part
		models[root] = part
	end
	
	local function removeMesh(ent)
		if models[ent.RootPart] then 
			models[ent.RootPart]:Destroy()
			models[ent.RootPart] = nil
		end
	end
	
	PlayerModel = vape.Categories.Render:CreateModule({
		Name = 'PlayerModel',
		Function = function(callback)
			if callback then 
				modelGeneration += 1
				local generation = modelGeneration
				if Local.Enabled then 
					PlayerModel:Clean(entitylib.Events.LocalAdded:Connect(function(ent)
						addMesh(ent, generation)
					end))
					PlayerModel:Clean(entitylib.Events.LocalRemoved:Connect(removeMesh))
					if entitylib.isAlive then 
						task.spawn(function()
							if generation == modelGeneration and PlayerModel.Enabled then
								addMesh(entitylib.character, generation)
							end
						end)
					end
				end
				PlayerModel:Clean(entitylib.Events.EntityAdded:Connect(function(ent)
					addMesh(ent, generation)
				end))
				PlayerModel:Clean(entitylib.Events.EntityRemoved:Connect(removeMesh))
				for _, ent in entitylib.List do 
					task.spawn(function()
						if generation == modelGeneration and PlayerModel.Enabled then
							addMesh(ent, generation)
						end
					end)
				end
			else
				modelGeneration += 1
				for _, part in models do 
					part:Destroy()
				end
				table.clear(models)
			end
		end,
		Tooltip = 'Change the player models to a Mesh'
	})
	Scale = PlayerModel:CreateSlider({
		Name = 'Scale',
		Min = 0,
		Max = 2,
		Default = 1,
		Decimal = 100,
		Function = function(val)
			for _, part in models do 
				part.Mesh.Scale = Vector3.one * val
			end
		end
	})
	for _, name in {'Rotation X', 'Rotation Y', 'Rotation Z'} do 
		table.insert(Rots, PlayerModel:CreateSlider({
			Name = name,
			Min = 0,
			Max = 360,
			Function = function(val)
				for root, part in models do 
					part.WeldConstraint.Enabled = false
					part.CFrame = root.CFrame * CFrame.Angles(math.rad(Rots[1].Value), math.rad(Rots[2].Value), math.rad(Rots[3].Value))
					part.WeldConstraint.Enabled = true
				end
			end
		}))
	end
	Local = PlayerModel:CreateToggle({
		Name = 'Local',
		Function = function()
			if PlayerModel.Enabled then 
				PlayerModel:Toggle()
				PlayerModel:Toggle()
			end
		end
	})
	Mesh = PlayerModel:CreateTextBox({
		Name = 'Mesh',
		Placeholder = 'mesh id',
		Function = function()
			for _, part in models do 
				part.Mesh.MeshId = Mesh.Value
			end
		end
	})
	Texture = PlayerModel:CreateTextBox({
		Name = 'Texture',
		Placeholder = 'texture id',
		Function = function()
			for _, part in models do 
				part.Mesh.TextureId = Texture.Value
			end
		end
	})
	
end)
	
run(function()
	local Radar
	local Targets
	local DotStyle
	local PlayerColor
	local Clamp
	local Reference = {}
	local bkg
	
	local function Added(ent)
		if not Targets.Players.Enabled and ent.Player then return end
		if not Targets.NPCs.Enabled and ent.NPC then return end
		if (not ent.Targetable) and (not ent.Friend) then return end
		if vape.ThreadFix then
			setthreadidentity(8)
		end
	
		local dot = Instance.new('Frame')
		dot.Size = UDim2.fromOffset(4, 4)
		dot.AnchorPoint = Vector2.new(0.5, 0.5)
		dot.BackgroundColor3 = entitylib.getEntityColor(ent) or Color3.fromHSV(PlayerColor.Hue, PlayerColor.Sat, PlayerColor.Value)
		dot.Parent = bkg
		local corner = Instance.new('UICorner')
		corner.CornerRadius = UDim.new(DotStyle.Value == 'Circles' and 1 or 0, 0)
		corner.Parent = dot
		local stroke = Instance.new('UIStroke')
		stroke.Color = Color3.new()
		stroke.Thickness = 1
		stroke.Transparency = 0.8
		stroke.Parent = dot
		Reference[ent] = dot
	end
	
	local function Removed(ent)
		local v = Reference[ent]
		if v then
			if vape.ThreadFix then
				setthreadidentity(8)
			end
			Reference[ent] = nil
			v:Destroy()
		end
	end
	
	Radar = vape:CreateOverlay({
		Name = 'Radar',
		Icon = getcustomasset('pistonware/assets/new/radaricon.png'),
		Size = UDim2.fromOffset(14, 14),
		Position = UDim2.fromOffset(12, 13),
		Function = function(callback)
			if callback then
				Radar:Clean(entitylib.Events.EntityRemoved:Connect(Removed))
				for _, v in entitylib.List do
					if Reference[v] then
						Removed(v)
					end
					Added(v)
				end
				Radar:Clean(entitylib.Events.EntityAdded:Connect(function(ent)
					if Reference[ent] then
						Removed(ent)
					end
					Added(ent)
				end))
				Radar:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function()
					for ent, dot in Reference do
						dot.BackgroundColor3 = entitylib.getEntityColor(ent) or Color3.fromHSV(PlayerColor.Hue, PlayerColor.Sat, PlayerColor.Value)
					end
				end))
				Radar:Clean(runService.RenderStepped:Connect(function()
					for ent, dot in Reference do
						if entitylib.isAlive then
							local dt = CFrame.lookAlong(entitylib.character.RootPart.Position, gameCamera.CFrame.LookVector * Vector3.new(1, 0, 1)):PointToObjectSpace(ent.RootPart.Position)
							dot.Position = UDim2.fromOffset(Clamp.Enabled and math.clamp(108 + dt.X, 2, 214) or 108 + dt.X, Clamp.Enabled and math.clamp(108 + dt.Z, 8, 214) or 108 + dt.Z)
						end
					end
				end))
			else
				for ent in Reference do
					Removed(ent)
				end
			end
		end
	})
	Targets = Radar:CreateTargets({
		Players = true,
		Function = function()
			if Radar.Button.Enabled then
				Radar.Button:Toggle()
				Radar.Button:Toggle()
			end
		end
	})
	DotStyle = Radar:CreateDropdown({
		Name = 'Dot Style',
		List = {'Circles', 'Squares'},
		Function = function(val)
			for _, dot in Reference do
				dot.UICorner.CornerRadius = UDim.new(val == 'Circles' and 1 or 0, 0)
			end
		end
	})
	PlayerColor = Radar:CreateColorSlider({
		Name = 'Player Color',
		Function = function(hue, sat, val)
			for ent, dot in Reference do
				dot.BackgroundColor3 = entitylib.getEntityColor(ent) or Color3.fromHSV(hue, sat, val)
			end
		end
	})
	bkg = Instance.new('Frame')
	bkg.Size = UDim2.fromOffset(216, 216)
	bkg.Position = UDim2.fromOffset(2, 2)
	bkg.BackgroundColor3 = Color3.new()
	bkg.BackgroundTransparency = 0.5
	bkg.ClipsDescendants = true
	bkg.Parent = Radar.Children
	local corner = Instance.new('UICorner')
	corner.CornerRadius = UDim.new(0, 8)
	corner.Parent = bkg
	local stroke = Instance.new('UIStroke')
	stroke.Thickness = 2
	stroke.Color = Color3.new()
	stroke.Transparency = 0.4
	stroke.Parent = bkg
	local line1 = Instance.new('Frame')
	line1.Size = UDim2.new(0, 2, 1, 0)
	line1.Position = UDim2.fromScale(0.5, 0.5)
	line1.AnchorPoint = Vector2.new(0.5, 0.5)
	line1.ZIndex = 0
	line1.BackgroundColor3 = Color3.new(1, 1, 1)
	line1.BackgroundTransparency = 0.5
	line1.BorderSizePixel = 0
	line1.Parent = bkg
	local line2 = line1:Clone()
	line2.Size = UDim2.new(1, 0, 0, 2)
	line2.Parent = bkg
	local bar = Instance.new('Frame')
	bar.Size = UDim2.new(1, -6, 0, 4)
	bar.Position = UDim2.fromOffset(3, 0)
	bar.BackgroundColor3 = Color3.fromHSV(0.44, 1, 1)
	bar.Parent = bkg
	local barcorner = Instance.new('UICorner')
	barcorner.CornerRadius = UDim.new(0, 8)
	barcorner.Parent = bar
	Radar:CreateColorSlider({
		Name = 'Bar Color',
		Function = function(hue, sat, val)
			bar.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
		end
	})
	Radar:CreateToggle({
		Name = 'Show Background',
		Default = true,
		Function = function(callback)
			bkg.BackgroundTransparency = callback and 0.5 or 1
			bar.BackgroundTransparency = callback and 0 or 1
			stroke.Transparency = callback and 0.4 or 1
		end
	})
	Radar:CreateToggle({
		Name = 'Show Cross',
		Default = true,
		Function = function(callback)
			line1.BackgroundTransparency = callback and 0.5 or 1
			line2.BackgroundTransparency = callback and 0.5 or 1
		end
	})
	Clamp = Radar:CreateToggle({
		Name = 'Clamp Radar',
		Default = true
	})
end)
	
run(function()
	local Search
	local List
	local Color
	local FillTransparency
	local Reference = {}
	local Candidates = {}
	local CandidatesInitialized = false
	local Folder = Instance.new('Folder')
	Folder.Parent = vape.gui

	local function Add(v)
		if Reference[v] then return end
		if not table.find(List.ListEnabled, v.Name) then return end
		if v:IsA('BasePart') or v:IsA('Model') then
			local size = v:IsA('Model') and v:GetExtentsSize() or v.Size
			local box = Instance.new('BoxHandleAdornment')
			box.AlwaysOnTop = true
			box.Adornee = v
			box.Size = size.Magnitude > 0.4 and size or Vector3.one
			box.ZIndex = 0
			box.Transparency = FillTransparency.Value
			box.Color3 = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
			box.Parent = Folder
			Reference[v] = box
			end
	end

	local function addCandidate(v)
		if not (v:IsA('BasePart') or v:IsA('Model')) then return end
		Candidates[v] = true
		if Search and Search.Enabled then
			Add(v)
		end
	end

	vape:Clean(workspace.DescendantAdded:Connect(addCandidate))
	vape:Clean(workspace.DescendantRemoving:Connect(function(v)
		Candidates[v] = nil
		if Reference[v] then
			Reference[v]:Destroy()
			Reference[v] = nil
		end
	end))

	Search = vape.Categories.Render:CreateModule({
		Name = 'Search',
		Function = function(callback)
			if callback then
				if not CandidatesInitialized then
					for _, v in workspace:GetDescendants() do
						addCandidate(v)
					end
					CandidatesInitialized = true
				end
				for v in Candidates do
					Add(v)
				end
			else
			Folder:ClearAllChildren()
			table.clear(Reference)
		end
		end,
		Tooltip = 'Draws box around selected parts\nAdd parts in Search frame'
	})
	List = Search:CreateTextList({
		Name = 'Parts',
		Function = function()
			if Search.Enabled then
				Search:Toggle()
				Search:Toggle()
			end
		end
	})
	Color = Search:CreateColorSlider({
		Name = 'Color',
		Function = function(hue, sat, val)
			for _, v in Reference do
				v.Color3 = Color3.fromHSV(hue, sat, val)
			end
		end
	})
	FillTransparency = Search:CreateSlider({
		Name = 'Transparency',
		Min = 0,
		Max = 1,
		Function = function(val)
			for _, v in Reference do
				v.Transparency = val
			end
		end,
	Decimal = 10
})
end)

--[[ The sessioninfo library is pure data with no GUI dependency, so it registers in its own
block ahead of the Session Info overlay. It used to be created at the tail of the overlay
block, meaning any failure in the overlay's instance work (or in anything before it, while
the runner was still unguarded) left vape.Libraries.sessioninfo unset -- and the place
files capture it into a file-local exactly once, so they then indexed nil for the rest of
the session no matter what universal did later. ]]
run(function()
	local sessioninfo = ensureSessionInfo()
	if not sessioninfo.Objects['Time Played'] then
		sessioninfo:AddItem('Time Played', os.clock(), function(value)
			return os.date('!%X', math.floor(os.clock() - value))
		end)
	end
end)

run(function()
	local SessionInfo
	local FontOption
	local Hide
	local TextSize
	local BorderColor
	local Title
	local TitleOffset = {}
	local Custom
	local CustomBox
	local infoholder
	local infolabel
	local infostroke
	
	SessionInfo = vape:CreateOverlay({
		Name = 'Session Info',
		Icon = getcustomasset('pistonware/assets/new/textguiicon.png'),
		Size = UDim2.fromOffset(16, 12),
		Position = UDim2.fromOffset(12, 14),
		Function = function(callback)
			if callback then
				local teleportedServers
				SessionInfo:Clean(playersService.LocalPlayer.OnTeleport:Connect(function()
					if not teleportedServers then
						teleportedServers = true
						queue_on_teleport("shared.vapesessioninfo = '"..httpService:JSONEncode(vape.Libraries.sessioninfo.Objects).."'")
					end
				end))
	
				if shared.vapesessioninfo then
					for i, v in httpService:JSONDecode(shared.vapesessioninfo) do
						if vape.Libraries.sessioninfo.Objects[i] and v.Saved then
							vape.Libraries.sessioninfo.Objects[i].Value = v.Value
						end
					end
				end
	
				repeat
					if vape.Libraries.sessioninfo then
						local stuff = {''}
						if Title.Enabled then
							stuff[1] = TitleOffset.Enabled and '<b>Session Info</b>\n<font size="4"> </font>' or '<b>Session Info</b>'
						end
	
						for i, v in vape.Libraries.sessioninfo.Objects do
							stuff[v.Index] = not table.find(Hide.ListEnabled, i) and i..': '..v.Function(v.Value) or false
						end
	
						--[[
							Rebuilt, not compacted in place.

							This used to walk `stuff` with next() and table.remove ENTRIES OUT OF IT
							mid-traversal, then resume next() from the key before the one it had just
							deleted. Removing a key other than the one next() is currently sitting on is
							undefined in Lua, and table.remove reindexes the array part -- so the walk
							could skip entries, revisit them, or take the VM down with it. That is the
							same hazard that made vape:Save crash while the payload was registering, and
							it is not catchable: it is a client crash, not an error.

							It only fires when the blacklist has entries, which is why a default install
							never sees it and a configured one dies a few seconds after the overlay is
							switched on.

							One pass into a fresh table costs nothing and cannot be undefined.
						]]
						if #Hide.ListEnabled > 0 then
							local kept = {}
							for index = 1, #stuff do
								local entry = stuff[index]
								if entry ~= false and entry ~= nil then
									table.insert(kept, entry)
								end
							end
							stuff = kept
						end
	
						if Custom.Enabled then
							table.insert(stuff, CustomBox.Value)
						end
	
						if not Title.Enabled then
							table.remove(stuff, 1)
						end
						infolabel.Text = table.concat(stuff, '\n')
						infolabel.FontFace = FontOption.Value
						infolabel.TextSize = TextSize.Value
						local size = getfontsize(removeTags(infolabel.Text), infolabel.TextSize, infolabel.FontFace)
						infoholder.Size = UDim2.fromOffset(size.X + 16, size.Y + (Title.Enabled and TitleOffset.Enabled and 4 or 16))
					end
	
					task.wait(1)
				until not SessionInfo.Button or not SessionInfo.Button.Enabled
			end
		end
	})
	FontOption = SessionInfo:CreateFont({
		Name = 'Font',
		Blacklist = 'Arial'
	})
	Hide = SessionInfo:CreateTextList({
		Name = 'Blacklist',
		Tooltip = 'Name of entry to hide.',
		Icon = getcustomasset('pistonware/assets/new/blockedicon.png'),
		Tab = getcustomasset('pistonware/assets/new/blockedtab.png'),
		TabSize = UDim2.fromOffset(21, 16),
		Color = Color3.fromRGB(250, 50, 56)
	})
	SessionInfo:CreateColorSlider({
		Name = 'Background Color',
		DefaultValue = 0,
		DefaultOpacity = 0.5,
		Function = function(hue, sat, val, opacity)
			infoholder.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
			infoholder.BackgroundTransparency = 1 - opacity
		end
	})
	BorderColor = SessionInfo:CreateColorSlider({
		Name = 'Border Color',
		Function = function(hue, sat, val, opacity)
			infostroke.Color = Color3.fromHSV(hue, sat, val)
			infostroke.Transparency = 1 - opacity
		end,
		Darker = true,
		Visible = false
	})
	TextSize = SessionInfo:CreateSlider({
		Name = 'Text Size',
		Min = 1,
		Max = 30,
		Default = 16
	})
	Title = SessionInfo:CreateToggle({
		Name = 'Title',
		Function = function(callback)
			if TitleOffset.Object then
				TitleOffset.Object.Visible = callback
			end
		end,
		Default = true
	})
	TitleOffset = SessionInfo:CreateToggle({
		Name = 'Offset',
		Default = true,
		Darker = true
	})
	SessionInfo:CreateToggle({
		Name = 'Border',
		Function = function(callback)
			infostroke.Enabled = callback
			BorderColor.Object.Visible = callback
		end
	})
	Custom = SessionInfo:CreateToggle({
		Name = 'Add custom text',
		Function = function(enabled)
			CustomBox.Object.Visible = enabled
		end
	})
	CustomBox = SessionInfo:CreateTextBox({
		Name = 'Custom text',
		Darker = true,
		Visible = false
	})
	infoholder = Instance.new('Frame')
	infoholder.BackgroundColor3 = Color3.new()
	infoholder.BackgroundTransparency = 0.5
	infoholder.Parent = SessionInfo.Children
	vape:Clean(SessionInfo.Children:GetPropertyChangedSignal('AbsolutePosition'):Connect(function()
		if vape.ThreadFix then
			setthreadidentity(8)
		end
		local newside = SessionInfo.Children.AbsolutePosition.X > (vape.gui.AbsoluteSize.X / 2)
		infoholder.Position = UDim2.fromScale(newside and 1 or 0, 0)
		infoholder.AnchorPoint = Vector2.new(newside and 1 or 0, 0)
	end))
	local sessioninfocorner = Instance.new('UICorner')
	sessioninfocorner.CornerRadius = UDim.new(0, 5)
	sessioninfocorner.Parent = infoholder
	infolabel = Instance.new('TextLabel')
	infolabel.Size = UDim2.new(1, -16, 1, -16)
	infolabel.Position = UDim2.fromOffset(8, 8)
	infolabel.BackgroundTransparency = 1
	infolabel.TextXAlignment = Enum.TextXAlignment.Left
	infolabel.TextYAlignment = Enum.TextYAlignment.Top
	infolabel.TextSize = 16
	infolabel.TextColor3 = Color3.new(1, 1, 1)
	infolabel.TextStrokeColor3 = Color3.new()
	infolabel.TextStrokeTransparency = 0.8
	infolabel.Font = Enum.Font.Arial
	infolabel.RichText = true
	infolabel.Parent = infoholder
	infostroke = Instance.new('UIStroke')
	infostroke.Enabled = false
	infostroke.Color = Color3.fromHSV(0.44, 1, 1)
	infostroke.Parent = infoholder
	addBlur(infoholder)
end)

if shared.PistonwareDeveloper == true then
	run(function()
		local KillauraInfo
		local FontOption
		local TextSize
		local BorderColor
		local Title
		local TitleOffset
		local infoholder
		local infolabel
		local infostroke
		local lifecycle = 0
		local activeRun

		local function stopRun(run)
			if not run or run.Cleaned then return end
			run.Cleaned = true
			if activeRun == run then
				activeRun = nil
			end
			lifecycle += 1

			local thread = run.Thread
			if thread and thread ~= coroutine.running() and coroutine.status(thread) ~= 'dead' then
				pcall(task.cancel, thread)
			end

			local performance = run.Performance
			if performance then
				pcall(function()
					performance:StopDiagnostics()
				end)
				pcall(function()
					performance:SetKillauraTelemetry(false)
				end)
				if run.WasPerformanceEnabled ~= nil then
					pcall(function()
						performance:SetEnabled(run.WasPerformanceEnabled)
					end)
				end
			end
			run.Thread = nil
			run.Performance = nil
			run.WasPerformanceEnabled = nil

			if infolabel then infolabel.Text = '' end
			if infoholder then infoholder.Visible = false end
		end

		local function getKillaura()
			local modules = vape.Modules
			return modules and modules.Killaura
		end

		local function formatMilliseconds(value)
			return type(value) == 'number' and value >= 0 and string.format('%.1f ms', value * 1000) or '--'
		end

		local function formatPing(value)
			return type(value) == 'number' and value >= 0 and string.format('%.0f ms', value) or '--'
		end

		local function formatRate(value)
			return type(value) == 'number' and string.format('%.2f/s', value) or '--'
		end

		local function formatCount(value)
			return type(value) == 'number' and tostring(math.floor(value + 0.5)) or '--'
		end

		local function formatPercent(value)
			return type(value) == 'number' and string.format('%.1f%%', value * 100) or '--'
		end

		local function formatMemory(value)
			return type(value) == 'number' and string.format('%.0f MB', value) or '--'
		end

		local function formatAge(now, timestamp)
			return type(timestamp) == 'number' and string.format('%.1fs ago', math.max(now - timestamp, 0)) or '--'
		end

		local function getTargetName(target)
			if not target then return 'none' end
			local name
			pcall(function()
				if type(target) == 'table' and target.Player then
					name = target.Player.DisplayName or target.Player.Name
				else
					name = target.Name
				end
			end)
			return removeTags(tostring(name or 'target'))
		end

		KillauraInfo = vape:CreateOverlay({
			-- Keep this category name stable so existing developer profiles continue to load.
			Name = 'Killaura Info',
			Icon = getcustomasset('pistonware/assets/new/targetinfo.png'),
			Size = UDim2.fromOffset(16, 12),
			Position = UDim2.fromOffset(12, 110),
			CategorySize = 240,
			Function = function(callback)
				if not callback then
					stopRun(activeRun)
					return
				end

				stopRun(activeRun)
				lifecycle += 1
				local currentLifecycle = lifecycle
				local performance = entitylib.Performance
				local run = {
					Performance = performance,
					WasPerformanceEnabled = performance:IsEnabled(),
					Thread = coroutine.running()
				}
				activeRun = run
				KillauraInfo:Clean(function()
					stopRun(run)
				end)

					performance:SetEnabled(true)
					performance:SetKillauraTelemetry(true)
					performance:StartDiagnostics()

					local previousStats = performance:Snapshot()
					local previousStatsAt = os.clock()
					if infoholder then infoholder.Visible = true end

					repeat
						local now = os.clock()
						local currentStats = performance:Snapshot()
						local statsElapsed = math.max(now - previousStatsAt, 0.001)
						local function statRate(name)
							return math.max((currentStats[name] or 0) - (previousStats[name] or 0), 0) / statsElapsed
						end
						local cacheHits = statRate('TargetCacheHits')
						local cacheRefreshes = statRate('TargetCacheRefreshes')
						local cacheTotal = cacheHits + cacheRefreshes
						local cacheRatio = cacheTotal > 0 and string.format('%.1f%%', cacheHits / cacheTotal * 100) or '--'
						local scanRate = statRate('TargetScans')
						local candidateRate = statRate('TargetCandidates')
						local raycastRate = statRate('Raycasts')
						local updateRate = statRate('EntityUpdates')
						previousStats = currentStats
						previousStatsAt = now

						local telemetry = performance:KillauraSnapshot(now)
						local diagnostics = performance:DiagnosticsSnapshot(now)
						local killaura = getKillaura()
						local status = killaura and (killaura.Enabled and 'ON' or 'OFF') or 'UNAVAILABLE'
						local render = diagnostics.Render
						local heartbeat = diagnostics.Heartbeat
						local ping = diagnostics.Ping
						local spikes = diagnostics.Spikes
						local corrections = diagnostics.Corrections
						local lines = {}
						local showTitle = not Title or Title.Enabled
						if showTitle then
							lines[#lines + 1] = TitleOffset and TitleOffset.Enabled and '<b>Developer Diagnostics</b>\n<font size="4"> </font>' or '<b>Developer Diagnostics</b>'
						end
						lines[#lines + 1] = 'Killaura: '..status..' | Target: '..getTargetName(telemetry.LastTarget)
						lines[#lines + 1] = 'Attempts: '..formatCount(telemetry.SwingCount)..' | Confirmed: '..formatCount(telemetry.ConfirmedCount)..' | Pending: '..formatCount(telemetry.PendingCount)
						lines[#lines + 1] = 'Expired: '..formatCount(telemetry.ExpiredCount)..' | Dropped: '..formatCount(telemetry.DroppedCount)
						lines[#lines + 1] = 'Finalized hit ratio: '..formatPercent(telemetry.Accuracy)..' | provisional '..formatPercent(telemetry.ProvisionalAccuracy)
						lines[#lines + 1] = 'Hit rate: '..formatRate(telemetry.HitRate)..' rolling 5s | Swing rate: '..formatRate(telemetry.SwingRate)
						lines[#lines + 1] = 'Hit gap: '..formatMilliseconds(telemetry.AverageHitGap)..' avg | Swing gap: '..formatMilliseconds(telemetry.AverageSwingGap)..' avg'
						lines[#lines + 1] = 'Confirm source: matched adapter event | Telemetry uptime: '..string.format('%.1fs', telemetry.Elapsed or 0)
						if diagnostics.Enabled then
							lines[#lines + 1] = 'Render FPS: '..formatCount(render.Fps)..' | 1% low: '..formatCount(render.Low1PercentFps)
							lines[#lines + 1] = 'Frame: '..formatMilliseconds(render.FrameAverage)..' avg | '..formatMilliseconds(render.FrameP95)..' p95 | '..formatMilliseconds(render.FrameMax)..' max'
							lines[#lines + 1] = 'Heartbeat: '..formatMilliseconds(heartbeat.Average)..' avg | '..formatMilliseconds(heartbeat.P95)..' p95 | '..formatMilliseconds(heartbeat.Max)..' max'
							lines[#lines + 1] = 'Ping: '..formatPing(ping.Current)..' now | '..formatPing(ping.Average)..' avg | '..formatPing(ping.P95)..' p95 | jitter '..formatPing(ping.Jitter)
							lines[#lines + 1] = 'Spikes/10s: render '..formatCount(spikes.Render)..' | heartbeat '..formatCount(spikes.Heartbeat)..' | ping '..formatCount(spikes.Network)
							lines[#lines + 1] = 'Last spikes: render '..formatMilliseconds(spikes.LastRender)..' | heartbeat '..formatMilliseconds(spikes.LastHeartbeat)..' | ping '..formatPing(spikes.LastNetwork)
							lines[#lines + 1] = 'Samples: render '..formatCount(render.Samples)..' | heartbeat '..formatCount(heartbeat.Samples)..' | ping '..formatCount(ping.Samples)
							lines[#lines + 1] = 'Correction signals: '..formatCount(corrections.Count)..' total | '..formatCount(corrections.Recent)..' recent | '..(corrections.LastReason or 'none')..' ('..formatAge(now, corrections.LastAt)..')'
							lines[#lines + 1] = 'Memory: '..formatMemory(diagnostics.Memory)
						else
							lines[#lines + 1] = 'Diagnostics sampler: unavailable'
						end
						lines[#lines + 1] = 'Targeting/s: scan '..formatRate(scanRate)..' | candidates '..formatRate(candidateRate)..' | raycast '..formatRate(raycastRate)
						lines[#lines + 1] = 'Cache: '..cacheRatio..' hit | entity updates '..formatRate(updateRate)

						infolabel.Text = table.concat(lines, '\n')
						infolabel.FontFace = FontOption.Value
						infolabel.TextSize = TextSize.Value
						local size = getfontsize(removeTags(infolabel.Text), infolabel.TextSize, infolabel.FontFace)
						infoholder.Size = UDim2.fromOffset(math.max(420, math.min(size.X + 16, 640)), size.Y + (showTitle and TitleOffset and TitleOffset.Enabled and 4 or 16))
						task.wait(0.25)
					until lifecycle ~= currentLifecycle or not KillauraInfo.Button or not KillauraInfo.Button.Enabled

				if activeRun == run then
					stopRun(run)
				end
			end
		})
		FontOption = KillauraInfo:CreateFont({
			Name = 'Font',
			Blacklist = 'Arial'
		})
		KillauraInfo:CreateColorSlider({
			Name = 'Background Color',
			DefaultValue = 0,
			DefaultOpacity = 0.5,
			Function = function(hue, sat, val, opacity)
				if infoholder then
					infoholder.BackgroundColor3 = Color3.fromHSV(hue, sat, val)
					infoholder.BackgroundTransparency = 1 - opacity
				end
			end
		})
		BorderColor = KillauraInfo:CreateColorSlider({
			Name = 'Border Color',
			Function = function(hue, sat, val, opacity)
				if infostroke then
					infostroke.Color = Color3.fromHSV(hue, sat, val)
					infostroke.Transparency = 1 - opacity
				end
			end,
			Darker = true,
			Visible = false
		})
		TextSize = KillauraInfo:CreateSlider({
			Name = 'Text Size',
			Min = 1,
			Max = 30,
			Default = 16
		})
		Title = KillauraInfo:CreateToggle({
			Name = 'Title',
			Function = function(callback)
				if TitleOffset and TitleOffset.Object then
					TitleOffset.Object.Visible = callback
				end
			end,
			Default = true
		})
		TitleOffset = KillauraInfo:CreateToggle({
			Name = 'Offset',
			Default = true,
			Darker = true
		})
		KillauraInfo:CreateToggle({
			Name = 'Border',
			Function = function(callback)
				if infostroke then infostroke.Enabled = callback end
				if BorderColor and BorderColor.Object then BorderColor.Object.Visible = callback end
			end
		})
		infoholder = Instance.new('Frame')
		infoholder.BackgroundColor3 = Color3.new()
		infoholder.BackgroundTransparency = 0.5
		infoholder.Parent = KillauraInfo.Children
		vape:Clean(KillauraInfo.Children:GetPropertyChangedSignal('AbsolutePosition'):Connect(function()
			if vape.ThreadFix then
				setthreadidentity(8)
			end
			local newside = KillauraInfo.Children.AbsolutePosition.X > (vape.gui.AbsoluteSize.X / 2)
			infoholder.Position = UDim2.fromScale(newside and 1 or 0, 0)
			infoholder.AnchorPoint = Vector2.new(newside and 1 or 0, 0)
		end))
		local infocorner = Instance.new('UICorner')
		infocorner.CornerRadius = UDim.new(0, 5)
		infocorner.Parent = infoholder
		infolabel = Instance.new('TextLabel')
		infolabel.Size = UDim2.new(1, -16, 1, -16)
		infolabel.Position = UDim2.fromOffset(8, 8)
		infolabel.BackgroundTransparency = 1
		infolabel.TextXAlignment = Enum.TextXAlignment.Left
		infolabel.TextYAlignment = Enum.TextYAlignment.Top
		infolabel.TextSize = 16
		infolabel.TextColor3 = Color3.new(1, 1, 1)
		infolabel.TextStrokeColor3 = Color3.new()
		infolabel.TextStrokeTransparency = 0.8
		infolabel.Font = Enum.Font.Arial
		infolabel.RichText = true
		infolabel.Parent = infoholder
		infostroke = Instance.new('UIStroke')
		infostroke.Enabled = false
		infostroke.Color = Color3.fromHSV(0.44, 1, 1)
		infostroke.Parent = infoholder
		addBlur(infoholder)
	end)
end

run(function()
	local Tracers
	local Targets
	local Color
	local Transparency
	local StartPosition
	local EndPosition
	local Teammates
	local DistanceColor
	local Distance
	local DistanceLimit
	local Behind
	local Reference = {}
	
	local function Added(ent)
		if not Targets.Players.Enabled and ent.Player then return end
		if not Targets.NPCs.Enabled and ent.NPC then return end
		if Teammates.Enabled and (not ent.Targetable) and (not ent.Friend) then return end
		if vape.ThreadFix then
			setthreadidentity(8)
		end
	
		local EntityTracer = Drawing.new('Line')
		EntityTracer.Thickness = 1
		EntityTracer.Transparency = 1 - Transparency.Value
		EntityTracer.Color = entitylib.getEntityColor(ent) or Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
		Reference[ent] = EntityTracer
	end
	
	local function Removed(ent)
		local v = Reference[ent]
		if v then
			if vape.ThreadFix then
				setthreadidentity(8)
			end
			Reference[ent] = nil
			pcall(function()
				v.Visible = false
				v:Remove()
			end)
		end
	end
	
	local function ColorFunc(hue, sat, val)
		if DistanceColor.Enabled then return end
		local tracerColor = Color3.fromHSV(hue, sat, val)
		for ent, EntityTracer in Reference do
			EntityTracer.Color = entitylib.getEntityColor(ent) or tracerColor
		end
	end
	
	local function Loop()
		local screenSize = vape.gui.AbsoluteSize
		local startVector = StartPosition.Value == 'Mouse' and inputService:GetMouseLocation() or Vector2.new(screenSize.X / 2, (StartPosition.Value == 'Middle' and screenSize.Y / 2 or screenSize.Y))
	
		for ent, EntityTracer in Reference do
			local distance = entitylib.isAlive and (entitylib.character.RootPart.Position - ent.RootPart.Position).Magnitude
			if Distance.Enabled and distance then
				if distance < DistanceLimit.ValueMin or distance > DistanceLimit.ValueMax then
					EntityTracer.Visible = false
					continue
				end
			end
	
			local pos = ent[EndPosition.Value == 'Torso' and 'RootPart' or 'Head'].Position
			local rootPos, rootVis = gameCamera:WorldToViewportPoint(pos)
			if not rootVis and Behind.Enabled then
				local tempPos = gameCamera.CFrame:PointToObjectSpace(pos)
				tempPos = CFrame.Angles(0, 0, (math.atan2(tempPos.Y, tempPos.X) + math.pi)):VectorToWorldSpace((CFrame.Angles(0, math.rad(89.9), 0):VectorToWorldSpace(Vector3.new(0, 0, -1))))
				rootPos = gameCamera:WorldToViewportPoint(gameCamera.CFrame:pointToWorldSpace(tempPos))
				rootVis = true
			end
	
			local endVector = Vector2.new(rootPos.X, rootPos.Y)
			EntityTracer.Visible = rootVis
			EntityTracer.From = startVector
			EntityTracer.To = endVector
			if DistanceColor.Enabled and distance then
				EntityTracer.Color = Color3.fromHSV(math.min((distance / 128) / 2.8, 0.4), 0.89, 0.75)
			end
		end
	end
	
	Tracers = vape.Categories.Render:CreateModule({
		Name = 'Tracers',
		Function = function(callback)
			if callback then
				Tracers:Clean(entitylib.Events.EntityRemoved:Connect(Removed))
				for _, v in entitylib.List do
					if Reference[v] then
						Removed(v)
					end
					Added(v)
				end
				Tracers:Clean(entitylib.Events.EntityAdded:Connect(function(ent)
					if Reference[ent] then
						Removed(ent)
					end
					Added(ent)
				end))
				Tracers:Clean(vape.Categories.Friends.ColorUpdate.Event:Connect(function()
					ColorFunc(Color.Hue, Color.Sat, Color.Value)
				end))
				Tracers:Clean(runService.RenderStepped:Connect(Loop))
			else
				for i in Reference do
					Removed(i)
				end
			end
		end,
		Tooltip = 'Renders tracers on players.'
	})
	Targets = Tracers:CreateTargets({
		Players = true,
		Function = function()
			if Tracers.Enabled then
				Tracers:Toggle()
				Tracers:Toggle()
			end
		end
	})
	StartPosition = Tracers:CreateDropdown({
		Name = 'Start Position',
		List = {'Middle', 'Bottom', 'Mouse'},
		Function = function()
			if Tracers.Enabled then
				Tracers:Toggle()
