run(function()
	local PromptChanger
	local Mode
	local Modifier
	local Range
	local originalRanges = {}
	local modified = {}
	local thread

	local function updatePrompt(prompt)
		callWithThreadFix(function()
			if not prompt or not prompt:IsA('ProximityPrompt') then return end
			if originalRanges[prompt] == nil then
				originalRanges[prompt] = prompt.MaxActivationDistance
			end
			prompt.MaxActivationDistance = Range.Value
		end)
	end

	local function updateAllPrompts()
		callWithThreadFix(function()
			for _, prompt in workspace:GetDescendants() do
				updatePrompt(prompt)
			end
		end)
	end

	local function applyHoldDuration(prompt)
		if not prompt or not prompt:IsA('ProximityPrompt') then return end
		if modified[prompt] == nil then
			modified[prompt] = prompt.HoldDuration
		end
		prompt.HoldDuration = modified[prompt] * (Modifier.Value / 100)
	end

	local function restorePrompts()
		if thread then
			task.cancel(thread)
			thread = nil
		end

		for prompt, distance in originalRanges do
			callWithThreadFix(function()
				if prompt.Parent then
					prompt.MaxActivationDistance = distance
				end
			end)
		end
		table.clear(originalRanges)

		for prompt, duration in modified do
			callWithThreadFix(function()
				if prompt.Parent then
					prompt.HoldDuration = duration
				end
			end)
		end
		table.clear(modified)
	end

	PromptChanger = vape.Categories.Utility:CreateModule({
		Name = 'PromptChanger',
		Function = function(callback)
			if callback then
				updateAllPrompts()
				PromptChanger:Clean(proxService.PromptShown:Connect(function(prompt)
					updatePrompt(prompt)
					if Mode.Value == 'Property' then
						applyHoldDuration(prompt)
					end
				end))
				PromptChanger:Clean(workspace.DescendantAdded:Connect(function(instance)
					updatePrompt(instance)
				end))

				if Mode.Value == 'Signal' then
					PromptChanger:Clean(proxService.PromptButtonHoldBegan:Connect(function(prompt, plr)
						if plr == lplr then
							thread = task.delay(prompt.HoldDuration * (Modifier.Value / 100), function()
								fireproximityprompt(prompt)
								thread = nil
							end)
						end
					end))
					PromptChanger:Clean(proxService.PromptButtonHoldEnded:Connect(function(prompt, plr)
						if plr == lplr and thread then
							task.cancel(thread)
							thread = nil
						end
					end))
				else
					PromptChanger:Clean(proxService.PromptHidden:Connect(function(prompt)
						if modified[prompt] then
							prompt.HoldDuration = modified[prompt]
							modified[prompt] = nil
						end
					end))
				end
			else
				restorePrompts()
			end
		end,
		Tooltip = 'Changes ProximityPrompt interaction range and hold time'
	})
	Mode = PromptChanger:CreateDropdown({
		Name = 'Mode',
		List = {'Signal', 'Property'},
		Tooltip = 'Signal - Fires the prompt after the adjusted delay\nProperty - Sets the HoldDuration property',
		Function = function()
			if PromptChanger.Enabled then
				PromptChanger:Toggle()
				PromptChanger:Toggle()
			end
		end
	})
	Range = PromptChanger:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 100,
		Default = 32,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end,
		Function = function()
			if PromptChanger.Enabled then
				for prompt in originalRanges do
					updatePrompt(prompt)
				end
			end
		end
	})
	Modifier = PromptChanger:CreateSlider({
		Name = 'Modifier',
		Min = 0,
		Max = 100,
		Default = 50,
		Suffix = '%',
		Function = function(val)
			for prompt, duration in modified do
				prompt.HoldDuration = duration * (val / 100)
			end
		end
	})
end)
	
run(function()
	local Blink
	local Type
	local AutoSend
	local AutoSendLength
	local oldphys, oldsend
	
	Blink = vape.Categories.Utility:CreateModule({
		Name = 'Blink',
		Function = function(callback)
			if callback then
				local teleported
				Blink:Clean(lplr.OnTeleport:Connect(function()
					setfflag('PhysicsSenderMaxBandwidthBps', '38760')
					setfflag('DataSenderRate', '60')
					teleported = true
				end))
	
				repeat
					local physicsrate, senderrate = '0', Type.Value == 'All' and '-1' or '60'
					if AutoSend.Enabled and tick() % (AutoSendLength.Value + 0.1) > AutoSendLength.Value then
						physicsrate, senderrate = '38760', '60'
					end
	
					if physicsrate ~= oldphys or senderrate ~= oldsend then
						setfflag('PhysicsSenderMaxBandwidthBps', physicsrate)
						setfflag('DataSenderRate', senderrate)
						oldphys, oldsend = physicsrate, senderrate
					end
	
					task.wait(0.03)
				until (not Blink.Enabled and not teleported)
			else
				if setfflag then
					setfflag('PhysicsSenderMaxBandwidthBps', '38760')
					setfflag('DataSenderRate', '60')
				end
				oldphys, oldsend = nil, nil
			end
		end,
		Tooltip = 'Chokes packets until disabled.'
	})
	Type = Blink:CreateDropdown({
		Name = 'Type',
		List = {'Movement Only', 'All'},
		Tooltip = 'Movement Only - Only chokes movement packets\nAll - Chokes remotes & movement'
	})
	AutoSend = Blink:CreateToggle({
		Name = 'Auto send',
		Function = function(callback)
			AutoSendLength.Object.Visible = callback
		end,
		Tooltip = 'Automatically send packets in intervals'
	})
	AutoSendLength = Blink:CreateSlider({
		Name = 'Send threshold',
		Min = 0,
		Max = 1,
		Decimal = 100,
		Darker = true,
		Visible = false,
		Suffix = function(val)
			return val == 1 and 'second' or 'seconds'
		end
	})
end)
	
local ChatSpammer
local Lines
local Mode
local Delay
local Hide
local RandomList = {}
local oldchat

ChatSpammer = vape.Categories.Utility:CreateModule({
	Name = 'ChatSpammer',
	Function = function(callback)
		if callback then
			if textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
				if Hide.Enabled and coreGui:FindFirstChild('ExperienceChat') then
					ChatSpammer:Clean(coreGui.ExperienceChat.appLayout.chatWindow.contentFrame.scrollingView.bottomLockedScrollView.scrollView.ChildAdded:Connect(function(msg)
						if msg.Name:sub(1, 2) == '0-' and msg.TextMessage.BodyText.Text == '<font color="#d4d4d4">You must wait before sending another message.</font>' then
							msg.Visible = false
						end
					end))
				end
			elseif replicatedStorage:FindFirstChild('DefaultChatSystemChatEvents') then
				if Hide.Enabled then
					oldchat = hookfunction(getconnections(replicatedStorage.DefaultChatSystemChatEvents.OnNewSystemMessage.OnClientEvent)[1].Function, function(data, ...)
						if data.Message:find('ChatFloodDetector') then return end
						return oldchat(data, ...)
					end)
				end
			else
				notif('ChatSpammer', 'unsupported chat', 5, 'warning')
				ChatSpammer:Toggle()
				return
			end

			local index = 1
			repeat
				local message = 'vxpe on top'
				if #Lines.ListEnabled > 0 then
					if Mode.Value == 'Order' then
						message = Lines.ListEnabled[index] or Lines.ListEnabled[1]
						index = (index % #Lines.ListEnabled) + 1
					else
						if #RandomList <= 0 then
							RandomList = table.clone(Lines.ListEnabled)
						end

						local entry = Random.new():NextInteger(1, #RandomList)
						message = RandomList[entry]
						table.remove(RandomList, entry)
					end
				end

				if textChatService.ChatVersion == Enum.ChatVersion.TextChatService then
					textChatService.ChatInputBarConfiguration.TargetTextChannel:SendAsync(message)
				else
					replicatedStorage.DefaultChatSystemChatEvents.SayMessageRequest:FireServer(message, 'All')
				end

				task.wait(Delay.Value)
			until not ChatSpammer.Enabled
		else
			if oldchat then
				hookfunction(getconnections(replicatedStorage.DefaultChatSystemChatEvents.OnNewSystemMessage.OnClientEvent)[1].Function, oldchat)
			end
		end
	end,
	Tooltip = 'Automatically types in chat'
})
Lines = ChatSpammer:CreateTextList({
	Name = 'Lines',
	Function = function()
		table.clear(RandomList)
	end
})
Mode = ChatSpammer:CreateDropdown({
	Name = 'Mode',
	List = {'Random', 'Order'}
})
Delay = ChatSpammer:CreateSlider({
	Name = 'Delay',
	Min = 0.1,
	Max = 10,
	Default = 1,
	Decimal = 10,
	Suffix = function(val)
		return val == 1 and 'second' or 'seconds'
	end
})
Hide = ChatSpammer:CreateToggle({
	Name = 'Hide Flood Message',
	Default = true,
	Function = function()
		if ChatSpammer.Enabled then
			ChatSpammer:Toggle()
			ChatSpammer:Toggle()
		end
	end
})
	
